import {pastoralIntroduction} from './pastoral.js';
import {concepts,glossary,analyze,groupSessions} from './study.js';
import {resources,methodGuide} from './resources.js';
import {parseProgress,toggleCompleted,moduleCompleted,sessionArtOpen,storyOpen} from './progress.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=s=>String(s||'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
const storage={get(k,f){try{return localStorage.getItem('luke-acts-'+k)||f}catch{return f}},set(k,v){try{localStorage.setItem('luke-acts-'+k,v)}catch{}}};
const shapes={leaf:'M4 20C1 10 9 3 21 3c0 12-7 20-17 17ZM4 20 16 8',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3ZM12 6v15',words:'M4 6h16M4 12h11M4 18h7M18 10l3 3-3 3M21 13h-6',concepts:'M9 18h6M10 21h4M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',comment:'M4 4h16v13H9l-5 4ZM8 8h8M8 12h5',link:'M10 14l4-4M8 16l-1 1a4 4 0 0 1-5-5l4-4a4 4 0 0 1 5 0M16 8l1-1a4 4 0 0 1 5 5l-4 4a4 4 0 0 1-5 0',lock:'M5 10h14v11H5ZM8 10V7a4 4 0 0 1 8 0v3M12 14v3'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${shapes[n]||shapes.book}"/></svg>`;
const legacyViews={words:'tools',concepts:'story'};
const navs=[['introduction','Introduction','Intro','leaf'],['reading','Read the text','Read','book'],['commentaries','Weekly studies','Studies','comment'],['story','The Story So Far','Story','concepts'],['tools','Bible Study Tools','Tools','words'],['resources','External Resources','Resources','link']];
let curriculum,bible,passages,catalog,reflections,journey,approvedStories,storyPromise,referencePromise,modalVersion=0;
let completed=[],progressSaved=true,reviewParticipant=false,lastGateSignature='';
let reflectionPreview=false;
const state={view:'introduction',week:Math.min(12,Math.max(1,Number(storage.get('week',1))||1)),rhythm:storage.get('rhythm','weekly'),scope:'week',category:'keywords',word:null,verse:null,context:true,tool:'words',size:Math.min(25,Math.max(16,Number(storage.get('size',20))||20)),module:'all',glossaryTheme:'current',glossaryQuery:''};
if(!['weekly','fortnightly'].includes(state.rhythm))state.rhythm='weekly';
document.documentElement.classList.toggle('dark',storage.get('theme','light')==='dark');
function theme(){const dark=document.documentElement.classList.contains('dark');$('#theme').textContent=dark?'☀':'☾';$('#theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`)}
theme();$('#theme').onclick=()=>{document.documentElement.classList.toggle('dark');storage.set('theme',document.documentElement.classList.contains('dark')?'dark':'light');theme()};
document.documentElement.style.setProperty('--reading-size',state.size+'px');
const date=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'Europe/Paris'}).format(new Date(s.length===10?s+'T12:00:00Z':s));
const fullDate=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Paris'}).format(new Date(s));
const session=()=>curriculum.sessions[state.week-1];
function currentGroup(){return groupSessions(curriculum.sessions,state.rhythm).find(g=>g.some(s=>s.number===state.week));}
function heading(n,title,copy,tag=''){return `<div class="section-head"><div class="section-title"><span class="step">${n}</span><div><h2>${title}</h2><p>${copy}</p></div></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
function nav(){ $('#navigation').innerHTML=navs.map(([id,label,short,shape],i)=>`<a class="nav-item ${state.view===id?'active':''}" href="#${id}" ${state.view===id?'aria-current="page"':''} aria-label="${label}">${icon(shape)}<span class="nav-text"><span class="desktop-label">${label}</span><span class="mobile-label">${short}</span></span><small>0${i+1}</small></a>`).join('');}
function go(view,scroll=true){view=legacyViews[view]||view;state.view=navs.some(n=>n[0]===view)?view:'introduction';history.replaceState(null,'','#'+state.view);nav();render();if(scroll)$('#view').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&navs.some(n=>a.hash==='#'+n[0])){e.preventDefault();go(a.hash.slice(1));}});
window.addEventListener('hashchange',()=>go(location.hash.slice(1),false));
function pickWeek(n){state.week=Number(n);state.word=null;state.verse=null;state.context=true;storage.set('week',state.week);}
function studySelector(){const groups=groupSessions(curriculum.sessions,state.rhythm);const index=groups.findIndex(g=>g.some(s=>s.number===state.week));return `<div class="study-selector"><div class="selector-fields"><label for="rhythm">Meeting rhythm<select id="rhythm"><option value="weekly" ${state.rhythm==='weekly'?'selected':''}>Every week</option><option value="fortnightly" ${state.rhythm==='fortnightly'?'selected':''}>Every two weeks</option></select></label><label for="week">${state.rhythm==='weekly'?'Study week':'Two-week gathering'}<select id="week">${groups.map((g,i)=>`<option value="${g[0].number}" ${i===index?'selected':''}>${g.map(s=>date(s.date)).join(' + ')} · ${g.length===1?g[0].passage:'Weeks '+g[0].number+' & '+g[1].number}</option>`).join('')}</select></label></div><div class="week-arrows"><button class="icon-button" data-week="${groups[index-1]?.[0].number||1}" ${index===0?'disabled':''} aria-label="Previous study">←</button><button class="icon-button" data-week="${groups[index+1]?.[0].number||12}" ${index===groups.length-1?'disabled':''} aria-label="Next study">→</button></div></div>${state.rhythm==='fortnightly'?'<p class="rhythm-note">Bring both passages and both sets of questions to your gathering. Use the second Narrative Bridge to carry the story into your next meeting.</p>':''}`;}
function pastoralIntro(){return `<section class="pastoral-intro" aria-labelledby="pastoral-welcome"><div class="eyebrow">GROWING TOGETHER IN THE WORD</div><h3 id="pastoral-welcome">${esc(pastoralIntroduction.title)}</h3><p class="pastoral-welcome">${esc(pastoralIntroduction.welcome)}</p><p class="pastoral-credit">Read, observe, interpret and apply each passage. At the end of a module, The Story So Far brings the scenes together around the question that has guided us.</p><a class="text-link reflection-reading" href="#story">See the story journey ↗</a></section>`;}
function intro(){return heading('01','The King has come','One story, twelve weeks, and room to grow together.','ACT I')+`<div class="welcome-copy"><p>${esc(curriculum.welcome)}</p><div class="series-facts"><span><strong>12</strong> weekly studies</span><span><strong>3</strong> modules + an interlude</span><span><strong>1</strong> connected story</span></div></div>${pastoralIntro()}<div class="section-subhead"><h3>Your journey through Act I</h3><span>October – December 2026</span></div><div class="module-grid">${curriculum.modules.slice(0,3).map(m=>`<article class="module-card">${moduleArt(m)}<div class="module-body"><div class="eyebrow">MODULE ${m.id} · ${esc(m.dates.replace(' 2026',''))}</div><h3>${esc(m.name)}</h3><p class="big-question">${esc(m.question)}</p><p>${esc(m.description)}</p><button class="text-link" data-module="${m.id}">Explore this module <span aria-hidden="true">↗</span></button></div></article>`).join('')}</div><div class="interlude"><span class="step">12</span><div><div class="eyebrow">28 DECEMBER · INTERLUDE</div><h3>Thirty Years Later…</h3><p>${esc(curriculum.modules[3].description)}</p><button class="text-link" data-read="12">Read Luke 3:1–22 ↗</button></div></div><section class="method-section"><h3>How we study together</h3><p>Begin with the Bible, listen carefully to one another, and let each scene lead the conversation.</p><div class="method-grid">${curriculum.methods.map((m,i)=>`<article><small>0${i+1}</small><h4>${m.title}</h4><p>${esc(m.text)}</p></article>`).join('')}</div></section><div class="two-rhythms"><h3>One study plan. Two ways to meet.</h3><p>If your group meets every week, follow one passage and its questions. If you meet every two weeks, bring the two most recent studies together, including both sets of questions. Everyone follows the same story, and the second Narrative Bridge carries a fortnightly group into its next gathering.</p><button class="text-link" data-open-classes>Choose your study ↗</button></div>${future()}`;}
function future(){return `<div class="future-act">${icon('lock')}<div><span class="eyebrow">CONTINUING IN 2027</span><h3>Act II · The King begins his ministry</h3><p>Our journey will continue towards Jerusalem, the cross, the resurrection and the witness of the church. These later studies are not open yet; their dates and teaching will be announced.</p></div><span class="tag">LOCKED</span></div>`;}
function highlighted(text){if(!state.word)return esc(text);const forms=[...state.word.forms].sort((a,b)=>b.length-a.length).map(f=>f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const re=new RegExp(`\\b(${forms.join('|')})(?:[’']s)?\\b`,'gi');let output='',last=0;for(const match of text.matchAll(re)){output+=esc(text.slice(last,match.index))+`<mark>${esc(match[0])}</mark>`;last=match.index+match[0].length;}return output+esc(text.slice(last));}
function chapter(s){return bible.chapters[s.book+'.'+s.chapter];}
function readVerses(s){return state.context?Object.entries(chapter(s).verses).map(([verse,text])=>({verse:Number(verse),text,key:`${s.book}.${s.chapter}.${verse}`})):s.verses;}
function reading(){
 return heading('02','Read the text','Read the whole chapter, with this week’s passage highlighted. Let the text lead the conversation.','WEB')+studySelector()+previewControl()+currentGroup().map(s=>{
  const m=curriculum.modules.find(m=>m.id===s.module),c=chapter(s);
  const verses=Object.entries(c.verses).map(([n,text])=>{const v=Number(n),focus=v>=s.start&&v<=s.end,key=`${s.book}.${s.chapter}.${v}`;let copy=highlighted(text);
   if(s.partialEnd&&v===s.end){const excerpt=s.verses.at(-1).text;copy=`<span class="study-verse-part">${highlighted(excerpt)}</span><span class="context-remainder">${highlighted(text.slice(excerpt.length))}</span>`;}
   return `${v===s.start?`<div class="passage-start" id="study-start-${s.number}" tabindex="-1"><span class="eyebrow">THIS WEEK’S PASSAGE · ${esc(s.passage)}</span></div>`:''}<p id="verse-${s.number}-${v}" tabindex="-1" class="verse ${focus?'focus-verse':'context-verse'} ${s.partialEnd&&v===s.end?'partial-verse':''}"><span class="verse-num" aria-label="Verse ${v}">${v}</span>${copy}</p>${v===s.end?sceneConnections(s):''}`;
  }).join('');
  return `<article class="reading-session"><header class="reading-session-head"><span class="eyebrow">WEEK ${s.number} · ${date(s.date)} · ${moduleLabel(s.module).toUpperCase()}</span><h3>${esc(s.title)}</h3><div class="guiding-question"><span class="eyebrow">OUR MODULE QUESTION</span><p>${esc(m.question)}</p></div></header>${sessionArt(s)}<div class="paper chapter-paper"><div class="reader-toolbar"><div><strong>${esc(c.book)} ${s.chapter} · Complete chapter</strong><p class="annotation">The burgundy edge marks ${esc(s.passage)}. The surrounding verses remain visible for context.</p><button class="text-link" data-study-jump="${s.number}">Jump to the study passage ↓</button></div><div class="type-tools"><button data-size="-1" aria-label="Smaller Bible text">A−</button><button data-size="1" aria-label="Larger Bible text">A+</button></div></div>${state.word?`<div class="selected-info"><span>Highlighting <strong>${esc(state.word.word)}</strong></span><button data-clear>Clear ×</button></div>`:''}<div class="reading-text">${verses}</div><div class="scripture-credit">World English Bible Classic · Public domain. Scripture wording is unchanged. ${s.partialEnd?'The study highlights only the opening clause of Micah 5:5; the rest of the verse remains visible.':''}</div></div><section class="reading-discussion"><h3>Explore this scene together</h3>${questions(s)}</section>${completionControl(s)}<button class="text-link" data-study="${s.number}">See this week’s pastoral commentary status ↗</button></article>`;
 }).join('');
}
function verseLabel(key){const [b,c,v]=key.split('.');return `${bible.chapters[b+'.'+c]?.book||({'2Sam':'2 Samuel',Isa:'Isaiah',Mic:'Micah'}[b]||b)} ${c}:${v}`;}
const bookNames={Gen:'Genesis',Exod:'Exodus',Lev:'Leviticus',Num:'Numbers',Deut:'Deuteronomy',Josh:'Joshua',Judg:'Judges','1Sam':'1 Samuel','2Sam':'2 Samuel','1Kgs':'1 Kings','2Kgs':'2 Kings','1Chr':'1 Chronicles','2Chr':'2 Chronicles',Neh:'Nehemiah',Ps:'Psalms',Prov:'Proverbs',Eccl:'Ecclesiastes',Song:'Song of Solomon',Isa:'Isaiah',Jer:'Jeremiah',Lam:'Lamentations',Ezek:'Ezekiel',Dan:'Daniel',Hos:'Hosea',Obad:'Obadiah',Mic:'Micah',Nah:'Nahum',Hab:'Habakkuk',Zeph:'Zephaniah',Hag:'Haggai',Zech:'Zechariah',Mal:'Malachi',Matt:'Matthew',Rom:'Romans','1Cor':'1 Corinthians','2Cor':'2 Corinthians',Gal:'Galatians',Eph:'Ephesians',Phil:'Philippians',Col:'Colossians','1Thess':'1 Thessalonians','2Thess':'2 Thessalonians','1Tim':'1 Timothy','2Tim':'2 Timothy',Phlm:'Philemon',Heb:'Hebrews',Jas:'James','1Pet':'1 Peter','2Pet':'2 Peter','1John':'1 John','2John':'2 John','3John':'3 John',Rev:'Revelation'};
function refLabel(key){if(passages?.[key])return passages[key].label;const [a,b]=key.split('-');const [book,c,v]=a.split('.');const end=b?.split('.');return `${bookNames[book]||book} ${c}:${v}${b?'–'+(end[1]===c?end[2]:end[1]+':'+end[2]):''}`;}
function scopeSessions(){if(state.scope==='all')return curriculum.sessions;if(state.scope.startsWith('module-'))return curriculum.sessions.filter(s=>s.module===Number(state.scope.split('-')[1]));return currentGroup();}
function analysisVerses(){return scopeSessions().flatMap(s=>s.verses.map(v=>({...v,week:s.number,label:chapter(s).book+' '+s.chapter+':'+v.verse+(v.part||'')})));}
function wordChart(word,verses){const max=Math.max(...word.perVerse,1),width=verses.length>30?Math.max(660,verses.length*19):Math.max(260,Math.min(900,($('#view')?.clientWidth||700)-(matchMedia('(max-width:640px)').matches?38:56))),height=160;const pts=word.perVerse.map((n,i)=>({n,x:20+i*(width-40)/Math.max(1,verses.length-1),y:140-115*n/max}));return `<figure class="frequency-chart"><div class="pattern-heading"><span>THE INSIGHT IN REPETITION</span><strong>${word.count} occurrences · ${word.perVerse.filter(n=>n>0).length} verses</strong></div><div class="chart-scroll" tabindex="0" aria-label="Word distribution chart; scroll horizontally for long selections"><svg class="${verses.length<=30?'compact-chart':''}" preserveAspectRatio="none" viewBox="0 0 ${width} ${height}" width="${width}" height="160" role="img" aria-label="${esc(word.word)}: ${esc(verses.map((v,i)=>word.perVerse[i]?`${v.label}, ${word.perVerse[i]}`:'').filter(Boolean).join('; '))}"><line class="pattern-grid" x1="20" x2="${width-20}" y1="140" y2="140"/><polygon class="pattern-area" points="20,140 ${pts.map(p=>`${p.x},${p.y}`).join(' ')} ${width-20},140"/><polyline class="pattern-line" points="${pts.map(p=>`${p.x},${p.y}`).join(' ')}"/>${pts.map((p,i)=>`<circle class="pattern-point" cx="${p.x}" cy="${p.y}" r="${p.n?3.5:1.5}"><title>${esc(verses[i].label)}: ${p.n}</title></circle>${i===0||i===pts.length-1||verses[i].week!==verses[i-1]?.week?`<text x="${p.x}" y="158" text-anchor="${i===0?'start':i===pts.length-1?'end':'middle'}">${esc(verses[i].label)}</text>`:''}`).join('')}</svg></div><figcaption>Read from left to right in study order. A higher peak means that this word appears more often in that verse. These are English word counts, not a count of the original Hebrew or Greek words.</figcaption><div class="occurrence-links">${verses.map((v,i)=>word.perVerse[i]?`<button class="word-pill" data-hit="${v.week}:${v.verse}">${esc(v.label)} <b>${word.perVerse[i]}</b></button>`:'').join('')}</div></figure>`;}
function words(){const verses=analysisVerses(),list=analyze(verses,state.category);let word=state.word?list.find(w=>w.word===state.word.word):list[0];state.word=word||null;const max=list[0]?.count||1;return '<h3 class="tool-heading">Repeated words</h3><p class="info-note">Notice where words return, then follow the pattern back into the passage.</p>'+studySelector()+`<div class="analysis-controls"><label for="scope">Explore repetitions in<select id="scope"><option value="week" ${state.scope==='week'?'selected':''}>This ${state.rhythm==='weekly'?'week':'gathering'}</option>${curriculum.modules.map(m=>`<option value="module-${m.id}" ${state.scope==='module-'+m.id?'selected':''}>${m.id===4?'Interlude':'Module '+m.id} · ${esc(m.name)}</option>`).join('')}<option value="all" ${state.scope==='all'?'selected':''}>All of Act I · 12 passages</option></select></label><div class="tabs" aria-label="Word category"><button data-category="keywords" class="${state.category==='keywords'?'active':''}" aria-pressed="${state.category==='keywords'}">Key words</button><button data-category="actions" class="${state.category==='actions'?'active':''}" aria-pressed="${state.category==='actions'}">Action words</button></div></div><p class="info-note">Select a word to explore it. Larger capsules appear more often. Related English forms are grouped where they are listed below; common linking words are left out of the key-word list.</p><div class="paper word-cloud">${list.slice(0,50).map(w=>{const ratio=w.count/max,tier=ratio>=.8?5:ratio>=.5?4:ratio>=.3?3:ratio>=.2?2:1;return `<button class="word-cloud-pill frequency-${tier} ${word?.word===w.word?'active':''}" data-word="${esc(w.word)}" aria-pressed="${word?.word===w.word}" aria-label="${esc(w.word)}, ${w.count} occurrences"><span>${esc(w.word)}</span><b>${w.count}</b></button>`}).join('')||'<p>No repeated words in this category. Try a wider selection.</p>'}</div>${list.length>50?'<p class="annotation">Showing the 50 most frequent terms in this selection.</p>':''}${word?`<section class="word-insight" id="word-insight"><span class="eyebrow">WORD INSIGHT</span><h3>${esc(word.word)}</h3><div class="word-meaning">${paragraphs(word.definition)}</div><p class="annotation">Counted forms: ${esc(word.forms.join(', '))}.</p>${wordChart(word,verses)}</section>`:''}`;}
const moduleLabel=id=>id===4?'Interlude':'Module '+id;
const moduleState=id=>{const source=reflections?.modules.find(m=>m.id===id),full=approvedStories?.modules.find(m=>m.id===id);return {...source,...(full?.reading?full:{}),id,releaseAt:journey.storyDates[id],released:Date.now()>=Date.parse(journey.storyDates[id]),available:storyAvailable(id)};};
const currentModule=()=>[...curriculum.sessions].reverse().find(s=>Date.now()>=Date.parse(lessonMeta(s)?.releaseAt))?.module||1;
const glossaryModule=g=>curriculum.sessions[g.week-1].module;
function previewControl(){
 if(reflections?.review)return `<aside class="pastor-preview is-preview"><div><strong>${reviewMode()?'Review edition · All sessions visible':'Review edition · Participant experience'}</strong><p>${reviewMode()?'All twelve scenes and four story readings are visible for review.':'Images and story readings now follow the participant rules.'} Review progress is separate from participant progress.</p></div><button class="secondary-button" data-review-toggle>${reviewMode()?'Preview participant experience':'Show all for review'}</button><a class="text-link" href="./#story">Open participant site ↗</a></aside>`;
 return '';
}
async function openModuleReading(id,sectionId=null){
 if(!storyAvailable(id))return;
 try{await ensureStories()}catch{showToast('The reading could not be loaded. Please try again.');return}
 const module=moduleState(id),reading=module?.reading;
 if(!module?.available||!reading)return;
 const blocks=section=>section.blocks.map(b=>b.kind==='quote'?`<blockquote class="module-scripture"><cite>${esc(b.reference)}</cite>${paragraphs(b.text)}</blockquote>`:b.kind==='heading'?`<h4>${esc(b.text)}</h4>`:paragraphs(b.text)).join('');
 openDialog(`${reviewMode()?'REVIEW EDITION · ':reflections.preview&&!module.released?'PASTOR PREVIEW · ':''}${moduleLabel(id).toUpperCase()} · CONTINUOUS READING`,reading.title,
 `<div class="module-reading-meta">${reading.wordCount.toLocaleString('en-GB')} words · About ${Math.ceil(reading.wordCount/180)} minutes</div><div class="module-reading-content"><p class="reflection-lead">${esc(reading.introduction)}</p>${reading.sections.length>1?`<nav class="reading-contents" aria-label="In this reading">${reading.sections.map(s=>`<button class="word-pill" data-reading-section="${s.id}">${esc(s.title)} ↓</button>`).join('')}</nav>`:''}${reading.sections.map(s=>`<section class="module-reading-section" id="reading-${s.id}" tabindex="-1"><img src="./assets/${s.image}" alt="${esc(s.alt)}" width="1774" height="887" loading="lazy"><h3>${esc(s.title)}</h3>${blocks(s)}</section>`).join('')}<section class="reading-discussion"><span class="eyebrow">TALK TOGETHER</span><h3>Bring the reading into daily life</h3><ol>${reading.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section></div><button class="text-link" data-read="${curriculum.sessions.find(s=>s.module===id).number}">Read the module’s opening Bible passage ↗</button><p class="pastoral-credit">${esc(reading.credit)}</p>`);
 wireModal();
 $('#dialog-body').querySelectorAll('[data-reading-section]').forEach(button=>button.onclick=()=>$('#reading-'+button.dataset.readingSection).focus());
 if(sectionId)requestAnimationFrame(()=>$('#reading-'+sectionId)?.focus());
}
function openConcept(index){const card=concepts[index];if(card)openModuleReading(card.module,'theme-'+index);}
function filterGlossary(){
 const q=state.glossaryQuery.trim().toLowerCase(),active=state.glossaryTheme==='current'?currentModule():Number(state.glossaryTheme);
 const found=glossary.filter(g=>(state.glossaryTheme==='all'||glossaryModule(g)===active)&&(g.word+' '+g.forms.join(' ')+' '+g.definition).toLowerCase().includes(q));
 $('#glossary-list').innerHTML=found.map(glossaryItem).join('')||'<p class="annotation">No matching terms. Try a different word, or choose Browse all terms.</p>';
 $('#glossary-status').textContent=`${found.length} of ${glossary.length} terms${state.glossaryTheme==='current'?' · '+moduleLabel(active):''}`;
 $('#glossary-list').querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.read);go('reading')});
}
function jumpToGlossary(word){closeDialog();state.tool='glossary';state.glossaryTheme='all';state.glossaryQuery=word;go('tools',false);$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});const match=[...$('#glossary-list').querySelectorAll('details')].find(el=>el.querySelector('summary span').textContent===word);if(match)match.open=true;}
function moduleReflections(m){
 const available=moduleState(m.id),cards=concepts.map((c,index)=>({...c,index})).filter(c=>c.module===m.id),ready=available.available,done=moduleCompleted(m.id,curriculum.sessions,completed),total=curriculum.sessions.filter(s=>s.module===m.id).length,count=curriculum.sessions.filter(s=>s.module===m.id&&completed.includes(s.number)).length;
 return `<section class="reflection-module ${ready?'is-open':'is-locked'}" aria-labelledby="reflection-module-${m.id}"><header class="reflection-module-head"><div><span class="eyebrow">${moduleLabel(m.id).toUpperCase()} · ${esc(m.dates)}</span><h3 id="reflection-module-${m.id}">${esc(m.name)}</h3></div><span class="module-status">${ready?'':icon('lock')}${reviewMode()?'Open for review':done?'Module completed':ready?'Open for reflection':'Read the scenes first'}</span></header><div class="guiding-question"><span class="eyebrow">THE QUESTION THAT CONNECTS THIS MODULE</span><p>${esc(m.question)}</p></div><p class="module-release">${count} of ${total} sessions completed. ${journey.storyUnlock==='completion-only'?'Complete every session to open this reflection.':`Opens when you complete this module, or on ${fullDate(available.releaseAt)} · Paris time.`}</p>${ready?`<div class="module-reading-invitation"><div><span class="eyebrow">GATHER THE STORY TOGETHER</span><p>${esc(available.reading?.introduction||m.description)}</p>${available.reading?`<small>${available.reading.wordCount.toLocaleString('en-GB')} words · About ${Math.ceil(available.reading.wordCount/180)} minutes</small>`:''}</div><button class="primary-button" data-module-reading="${m.id}">Read the ${m.id===4?'interlude':'module'} reflection ↗</button></div><div class="concept-grid">${cards.map(c=>`<article class="concept-card"><img class="theme-image" src="./assets/${c.image}" alt="${esc(c.alt)}" loading="lazy"><span class="eyebrow">${esc(c.reference)}</span><h4>${esc(c.title)}</h4><button class="text-link" data-concept="${c.index}">Follow this thread in the story ↗</button></article>`).join('')}</div>`:`${lockedCover()}<p class="annotation">Finish the module’s studies, then return here to reflect on how the scenes fit together.</p><button class="text-link" data-module="${m.id}">Continue this module ↗</button>`}</section>`;
}
function conceptsView(){return heading('04','The Story So Far','Pause at the end of a module and see how its scenes belong to one story.','3 MODULES + INTERLUDE')+previewControl()+progressSummary()+`<p class="info-note">These readings bring together the themes you have explored. They open after you complete the module${journey.storyUnlock==='completion-only'?'':', or when its study period has finished'}. The Bible readings, questions and study tools are always available.</p><nav class="module-jump" aria-label="Jump to a story module">${curriculum.modules.map(m=>`<button class="word-pill" data-module-jump="${m.id}">${moduleLabel(m.id)}</button>`).join('')}</nav>${curriculum.modules.map(moduleReflections).join('')}`;}
function glossaryView(){return `<section class="pastoral-glossary" aria-labelledby="glossary-heading"><div class="glossary-head"><div><h3 id="glossary-heading">A glossary for the journey</h3><p>${glossary.length} words and ideas, explained in everyday English. All definitions are available from the beginning.</p></div></div><div class="glossary-tools"><label for="glossary-search">Find a word or an idea<input id="glossary-search" type="search" placeholder="For example: grace, promise, incarnation…" value="${esc(state.glossaryQuery)}"></label><label for="glossary-theme">Explore by module<select id="glossary-theme"><option value="current" ${state.glossaryTheme==='current'?'selected':''}>Current module · ${moduleLabel(currentModule())}</option><option value="all" ${state.glossaryTheme==='all'?'selected':''}>Browse all terms</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${state.glossaryTheme===String(m.id)?'selected':''}>${moduleLabel(m.id)} · ${esc(m.name)}</option>`).join('')}</select></label></div><p class="annotation">Before the first opening, Current module shows Module 1. These definitions help us read; they are not additional words counted in the Bible text.</p><p id="glossary-status" class="glossary-count" role="status"></p><div id="glossary-list" class="glossary-list"></div></section>`;}

function glossaryItem(g){return `<details class="glossary-item"><summary><span>${esc(g.word)}</span><b aria-hidden="true">+</b></summary><div class="definition"><p>${esc(g.definition)}</p><p class="glossary-context">Explore alongside ${esc(g.reference)}</p><button class="text-link" data-read="${g.week}">Open the related Act I reading ↗</button></div></details>`;}
function questions(s){return `<div class="question-set">${[['observation','Observation'],['interpretation','Interpretation'],['application','Application']].map(([key,label],i)=>`<section class="study-question"><span class="question-label">0${i+1} · ${label}</span><p>${esc(s[key])}</p></section>`).join('')}${narrativeReturn(s)}<section class="narrative-bridge"><span class="eyebrow">NARRATIVE BRIDGE · KEEP THE STORY CONNECTED</span><p>${esc(s.bridge)}</p></section></div>`;}
function lessonMeta(s){return catalog?.lessons?.find(l=>l.id===s.id)}
function statusCard(s){const l=lessonMeta(s);if(l?.status==='available')return `<div class="commentary-ready"><span>Pastoral commentary is available</span><button class="primary-button" data-lesson="${s.id}">Read commentary ↗</button></div>`;return `<div class="awaiting-commentary">${icon('lock')}<div><strong>${l?.status==='scheduled'?'Commentary scheduled':'Waiting for content from Pastors'}</strong><p>${l?`Planned opening: ${fullDate(l.releaseAt)} · Paris time. `:''}The study questions above are ready to use. A pastoral commentary opens only when its teaching has been supplied and its release time has arrived.</p></div></div>`;}
function commentaryView(){const group=currentGroup();return heading('03','Weekly studies & commentaries','Read the passage, discuss the questions, and carry the story into your week.')+studySelector()+previewControl()+progressSummary()+`<div class="curriculum-note"><p>The questions and Narrative Bridges below come from the EIC Paris Act I curriculum. Weekly pastoral commentaries will appear alongside them as they are supplied.</p></div>${group.map(s=>`<article class="session-guide"><header><span class="eyebrow">WEEK ${s.number} · ${date(s.date)} · ${s.module===4?'INTERLUDE':'MODULE '+s.module}</span><h3>${esc(s.title)}</h3><button class="text-link" data-read="${s.number}">${esc(s.passage)} · Read the text ↗</button></header>${sessionArt(s)}${questions(s)}${completionControl(s)}${statusCard(s)}${s.leaderNote?`<details class="leader-note"><summary>For group leaders <b>+</b></summary><p>${esc(s.leaderNote)}</p></details>`:''}</article>`).join('')}<details class="commentary-method"><summary>What will the weekly commentary help us explore? <b>+</b></summary><p>It gives historical and theological background without doing the group’s thinking. Each commentary follows these four questions.</p><div class="method-grid">${curriculum.lenses.map(l=>`<article><h4>${l.title}</h4><p>${esc(l.text)}</p></article>`).join('')}</div></details><section class="all-studies"><div class="section-subhead"><h3>All twelve weeks</h3><label for="module-filter" class="sr-only">Filter study weeks by module</label><select id="module-filter"><option value="all">All modules</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${state.module===String(m.id)?'selected':''}>${m.id===4?'Interlude':'Module '+m.id}</option>`).join('')}</select></div><div class="schedule-list">${curriculum.sessions.filter(s=>state.module==='all'||s.module===Number(state.module)).map(s=>`<button class="schedule-item ${group.some(g=>g.number===s.number)?'current':''}" data-study="${s.number}">${sessionArt(s,true)}<span class="schedule-date">${date(s.date)}</span><span><strong>${esc(s.title)}</strong><small>${esc(s.passage)}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div></section>${future()}`;}
function resourcesView(){return heading('06','External Resources','Choose the tool that helps with the question you are asking.','11 TOOLS')+`<section class="resource-intro"><h3>Start with Scripture. Then explore.</h3><p>These links bring together the tools from both pages of the D-Groups Bible Study Resources guide. Use them after reading the passage for yourself, and bring questions that remain to your group.</p></section>${['Historical setting','Study the passage','Places and words'].map((category,i)=>`<section class="resource-section"><h3>${category}</h3><div class="resource-grid">${resources.filter(r=>r[2]===category).map(([name,url,,copy])=>`<a class="resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><span class="resource-number">${icon(i===0?'leaf':i===1?'book':'link')}</span><h4>${name}</h4><p>${copy}</p><small>${new URL(url).hostname}</small><span class="text-link">Open resource ↗</span></a>`).join('')}</div></section>`).join('')}<section class="method-section"><h3>A simple guide for your time together</h3><p>Adapted from the D-Groups study method: observe, interpret, apply, encourage one another and pray.</p>${methodGuide.map(([title,copy],i)=>`<details class="method-detail"><summary><span>0${i+1} · ${title}</span><b>+</b></summary><p>${copy}</p></details>`).join('')}</section>`;}
function render(){if(!curriculum)return;$('#view').innerHTML=`<div class="study-panel">${({introduction:intro,reading,tools:toolsView,story:conceptsView,commentaries:commentaryView,resources:resourcesView}[state.view])()}</div>`;wire();lastGateSignature=gateSignature();}
function openDialog(kicker,title,body){modalVersion++;$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}`;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;return modalVersion;}
function closeDialog(){modalVersion++;$('#detail').close();}
$('#close-dialog').onclick=closeDialog;$('#detail').addEventListener('cancel',()=>modalVersion++);
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
function allRefs(key){state.verse=key;const refs=bible.references[key]||[];openDialog('TSK-BASED CROSS REFERENCES',verseLabel(key),`<p>These ${refs.length} connections come from OpenBible’s TSK-based dataset and are ordered by community votes. They are starting points for careful comparison, not a ranking of biblical authority.</p>${refs.map(r=>`<button class="reference-row" data-ref="${r.ref}"><span>${esc(refLabel(r.ref))}</span><small>${r.votes} votes ↗</small></button>`).join('')||'<p>No connections are included for this verse in the supplied dataset.</p>'}`);wireModal();}
async function loadReferences(){if(passages)return passages;if(!referencePromise)referencePromise=fetchJSON('./references.json').then(data=>passages=data).catch(e=>{referencePromise=null;throw e});return referencePromise;}
async function openReference(ref){const version=openDialog('WORLD ENGLISH BIBLE',refLabel(ref),'<p role="status">Opening the connected passage…</p>');try{await loadReferences();if(version!==modalVersion||!$('#detail').open)return;const p=passages[ref];if(!p)throw Error('Missing reference');$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(p.label)}</h2>${p.verses.map(v=>`<p class="scripture-quote"><sup>${v.chapter}:${v.verse}</sup>${esc(v.text)}</p>`).join('')}<p>Read the surrounding chapter before deciding how the passages connect.</p><a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Read the chapter at eBible.org ↗</a>${state.verse?`<br><button class="text-link" data-all-refs="${state.verse}">← Back to all connections</button>`:''}`;wireModal();}catch{if(version===modalVersion)$('#dialog-body').innerHTML=`<h2 id="dialog-title">Unable to load this passage</h2><p>Please check your connection and try again.</p><button class="primary-button" data-ref="${ref}">Try again</button>`;wireModal();}}
function guide(n){const s=curriculum.sessions[n-1];openDialog(`WEEK ${s.number} · ${date(s.date)}`,s.title,`<p>${esc(s.passage)}</p>${questions(s)}<button class="primary-button" data-study="${s.number}">Open the study page</button>`);wireModal();}
async function openLesson(id){const l=catalog.lessons.find(l=>l.id===id);if(l?.status!=='available')return;const version=openDialog('PASTORAL COMMENTARY',l.title,'<p role="status">Opening commentary…</p>');try{const data=await fetchJSON(`${$('meta[name="lesson-base"]').content}/${encodeURIComponent(id)}/lesson.json`,{cache:'no-store'});if(version!==modalVersion||!$('#detail').open)return;$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(data.title)}</h2>${paragraphs(data.introduction)}${data.points.map((p,i)=>`<section><h3>${i+1}. ${esc(p.title)}</h3><div class="point-reference">${esc(p.reference)}</div>${p.image?`<img src="${$('meta[name="lesson-base"]').content}/${id}/${encodeURIComponent(p.image)}" alt="${esc(p.alt)}" loading="lazy">`:''}${paragraphs(p.text)}</section>`).join('')}<h3>A final word</h3>${paragraphs(data.finalWord)}<p class="annotation">Teaching supplied by the pastors of EIC Paris.</p>`;}catch{if(version===modalVersion)$('#dialog-body').innerHTML='<h2 id="dialog-title">Commentary unavailable</h2><p>Please try again later. The teaching may not yet have reached its release time.</p>';}}
function wireModal(){ $('#dialog-body').querySelectorAll('[data-glossary-jump]').forEach(b=>b.onclick=()=>jumpToGlossary(b.dataset.glossaryJump)); $('#dialog-body').querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));$('#dialog-body').querySelectorAll('[data-all-refs]').forEach(b=>b.onclick=()=>allRefs(b.dataset.allRefs));$('#dialog-body').querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.study);go('commentaries')});$('#dialog-body').querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.read);go('reading')});}
function wire(){
 document.querySelectorAll('[data-module-reading]').forEach(b=>b.onclick=()=>openModuleReading(Number(b.dataset.moduleReading)));
 $('#preview-reflections')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{await loadReflections(!reflectionPreview);render()}catch{button.disabled=false;button.textContent='Unable to change view · try again'}});
 document.querySelectorAll('[data-module-jump]').forEach(b=>b.onclick=()=>$('#reflection-module-'+b.dataset.moduleJump).scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}));
 $('[data-glossary-all]')?.addEventListener('click',()=>{state.glossaryTheme='all';state.glossaryQuery='';render();$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start'})});
 $('#week')?.addEventListener('change',e=>{pickWeek(e.target.value);render();$('#week').focus()});
 $('#rhythm')?.addEventListener('change',e=>{state.rhythm=e.target.value;storage.set('rhythm',state.rhythm);state.word=null;state.verse=null;render();$('#rhythm').focus()});
 document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.week);render()});
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.read);go('reading')});
 document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.study);go('commentaries')});
 document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const m=Number(b.dataset.module);pickWeek(curriculum.sessions.find(s=>s.module===m).number);state.module=String(m);go('commentaries')});
 $('[data-open-classes]')?.addEventListener('click',()=>go('commentaries'));
 $('#context')?.addEventListener('change',e=>{state.context=e.target.checked;render();$('#context').focus()});
 document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.size=Math.min(25,Math.max(16,state.size+Number(b.dataset.size)));storage.set('size',state.size);document.documentElement.style.setProperty('--reading-size',state.size+'px')});
 document.querySelectorAll('[data-verse]').forEach(b=>b.onclick=()=>{state.verse=b.dataset.verse;if(matchMedia('(max-width:900px)').matches){allRefs(state.verse)}else{render();$(`[data-verse="${state.verse}"]`)?.focus({preventScroll:true})}});
 document.querySelectorAll('[data-all-refs]').forEach(b=>b.onclick=()=>allRefs(b.dataset.allRefs));
 document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));
 document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>guide(Number(b.dataset.guide)));
 $('[data-clear]')?.addEventListener('click',()=>{state.word=null;render()});
 $('#scope')?.addEventListener('change',e=>{state.scope=e.target.value;state.word=null;render();$('#scope').focus()});
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.word=null;render();$(`[data-category="${state.category}"]`).focus()});
 document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{state.word=analyze(analysisVerses(),state.category).find(w=>w.word===b.dataset.word);render();$('#word-insight').scrollIntoView({block:'nearest',behavior:'smooth'})});
 document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>{const [week,verse]=b.dataset.hit.split(':').map(Number);const word=state.word;pickWeek(week);state.word=word;state.rhythm='weekly';storage.set('rhythm','weekly');state.verse=`${session().book}.${session().chapter}.${verse}`;go('reading',false);requestAnimationFrame(()=>{$(`#verse-${week}-${verse}`)?.scrollIntoView({block:'center'});$(`#verse-${week}-${verse}`)?.focus({preventScroll:true})})});
 document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>openConcept(Number(b.dataset.concept)));
 wireJourney();
 if($('#glossary-list'))filterGlossary();
 $('#glossary-search')?.addEventListener('input',e=>{state.glossaryQuery=e.target.value;filterGlossary()});
 $('#glossary-theme')?.addEventListener('change',e=>{state.glossaryTheme=e.target.value;filterGlossary()});
 document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));
 $('#module-filter')?.addEventListener('change',e=>{state.module=e.target.value;render();$('#module-filter').focus()});
}
$('#sources').onclick=()=>openDialog('D-GROUPS · SOURCES & CREDITS','Read with care.',`<h3>Scripture</h3><p>The <a href="https://ebible.org/eng-web/" target="_blank" rel="noopener noreferrer">World English Bible Classic</a> is in the public domain. This app contains the twelve Act I readings and their seven surrounding chapters. Scripture is reproduced from the official eBible archive, without editorial headings or footnote markers. Micah 5:5a is an excerpt; its full verse is available in chapter context.</p><h3>Supporting scenes</h3><p>Each study includes two selected WEB passages to help explore the module question and the final Narrative Bridge. These passages use the existing Scripture imports without rewriting them. The short comparison prompts are editorial reading aids; participants can follow other observations and applications that arise from the texts.</p><h3>TSK-based cross references</h3><p>The <a href="https://www.openbible.info/labs/cross-references/" target="_blank" rel="noopener noreferrer">OpenBible.info dataset</a> draws primarily on the Treasury of Scripture Knowledge and includes additional connections. The app includes all 3,333 rows for the seven context chapters, with 2,733 distinct passages quoted from WEB. The dataset is used under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>, filtered and ordered by votes. The votes are a study aid, not a measure of biblical authority.</p><h3>Curriculum and resources</h3><p>The twelve passages, study questions, Narrative Bridges and module introductions come from EIC Paris’s “DGroups Curriculum Framework: From Bethlehem to the Nations, Act I”, dated October–December 2026. The study method is adapted from the D-Groups 1 Peter guide; its 2025 dates and readings do not apply to this series. Resource links come from both pages of the Bible Study Resources guide.</p><h3>Reading aids and art</h3><p>The four continuous module readings come from the teaching document supplied for Act I. They preserve the wording of selected paragraphs, with repeated material reduced to keep each module below 1,500 words. Scripture excerpts in those readings retain the wording and excerpt marks of the supplied document. These readings are available in a public review edition; the participant view opens the reflections at the end of each module or when all its studies are marked completed. The welcome, glossary and contextual word explanations are edited English reading aids informed by Christian Nartatez’s BodyOfDivinity archive. Principal materials include “Pacto y Palabra”, the Genesis 12 and 15 reflections, the Christmas reflection, the teaching on Christ’s humility and obedience, the confession of faith, the sermon “One God, the Father Almighty”, and studies in Galatians, Ephesians and Romans. The archive also contains quotations and research notes from other writers; these have not been reproduced as if they were the pastor’s original prose. The repeated-word explanations also follow the specific WEB passages; the archive provides their pastoral and theological frame. These reading aids were organised and rewritten with AI assistance and remain distinct from the weekly pastoral commentaries. The Low Poly illustrations with cel-style shading were generated with AI as symbolic illustrations, not archaeological reconstructions. The design follows the D-Groups and EIC Paris study apps.</p><h3>Your preferences</h3><p>Completed studies, meeting rhythm, selected week, theme and reading size stay in this browser. Progress is not synced between devices; clearing browser site data removes it. If storage is unavailable, completion lasts only for the current visit. Review-edition progress is kept separate. Completion can open session illustrations and module reflections early, but does not release unpublished pastoral teaching. They do not change the pastoral commentary release calendar. This app does not collect names or shared notes. Act II and later teaching are not included.</p>`);
async function fetchJSON(url,options){const r=await fetch(url,options);if(!r.ok)throw Error(`${r.status}`);return r.json();}
async function loadReflections(preview=false){
 const url=$('meta[name="reflection-catalog"]').content;
 const next=await fetchJSON(url+(preview&&url.includes('/api/')?'?preview=1':''),{cache:'no-store'});
 reflections=next;reflectionPreview=next.preview;
}
async function refreshReleases(){
 if(!curriculum)return;
 const before=JSON.stringify(reflections),beforeCatalog=JSON.stringify(catalog);
 try{await loadReflections(reflectionPreview);catalog=await fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'});if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();if(!$('#detail').open&&(before!==JSON.stringify(reflections)||beforeCatalog!==JSON.stringify(catalog)||lastGateSignature!==gateSignature()))render()}catch{/* Keep the last verified view; a reload retries the request. */}
}
window.addEventListener('focus',refreshReleases);
setInterval(()=>{if(!document.hidden)refreshReleases()},60000);
async function start(){try{[curriculum,bible,catalog,journey]=await Promise.all([fetchJSON('./curriculum.json'),fetchJSON('./data.json'),fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'}),fetchJSON('./journey.json')]);await loadReflections();completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();go(location.hash.slice(1)||'introduction',false);}catch{$('#view').innerHTML='<div class="error"><h2>The study could not be opened</h2><p>Please check your connection, then reload the page.</p><button id="retry" class="primary-button">Try again</button></div>';$('#retry').onclick=start}}
start();


function reviewMode(){return Boolean((reflections?.review&&!reviewParticipant)||reflections?.preview);}
function progressKey(){return reflections?.review?'review-progress-v1':'progress-v1';}
function readProgress(){try{const raw=localStorage.getItem('luke-acts-'+progressKey());progressSaved=true;return parseProgress(raw);}catch{progressSaved=false;return [];}}
function storyAvailable(id){return storyOpen(id,curriculum.sessions,completed,journey.storyDates[id],Date.now(),reviewMode(),journey.storyUnlock);}
function artAvailable(s){return sessionArtOpen(s.number,lessonMeta(s)?.releaseAt,completed,Date.now(),reviewMode());}
function gateSignature(){return JSON.stringify([curriculum.sessions.map(artAvailable),curriculum.modules.map(m=>storyAvailable(m.id))]);}
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function lockedCover(compact=false){return `<span class="series-cover ${compact?'compact-cover':''}"><img src="./assets/series-mosaic.webp" alt="${compact?'':esc(journey.seriesCover.alt)}" width="1774" height="887" loading="lazy"><span class="series-wordmark"><span class="series-lock">${icon('lock')}</span><strong>From Bethlehem<br>to the Nations</strong><small>D-GROUP BIBLE STUDY SERIES</small></span></span>`;}
function sessionArt(s,compact=false){const item=journey.sessions[s.number-1],open=artAvailable(s),done=completed.includes(s.number);return `<span class="session-art ${compact?'session-thumb':''}" data-session-art="${s.number}">${open?`<img src="./assets/${item.image}" alt="${compact?'':esc(item.alt)}" width="1774" height="887" loading="lazy">`:lockedCover(compact)}${done?'<span class="completed-badge">✓ Completed</span>':!open&&!compact?`<span class="art-unlock">Scene opens ${date(lessonMeta(s).releaseAt)} at 07:00 Paris, or when you complete this study.</span>`:''}</span>`;}
function moduleArt(m){const c=concepts.find(c=>c.module===m.id);return storyAvailable(m.id)?`<img src="./assets/${c.image}" alt="${esc(c.alt)}" width="1774" height="887" loading="lazy">`:lockedCover();}
function progressSummary(){return `<section class="journey-progress" aria-label="Your Act I progress"><div><strong>Your journey · ${completed.length} of 12 studies completed</strong><p>${reflections?.review?'Review progress is separate. ':''}${progressSaved?'Saved in this browser on this device. Clearing site data removes it; it does not sync to other devices.':'Browser storage is unavailable. Your progress will last only for this visit.'}</p></div><progress max="12" value="${completed.length}" aria-label="Completed studies">${completed.length} of 12</progress></section>`;}
function completionControl(s){const done=completed.includes(s.number),ready=storyAvailable(s.module);return `<section class="completion-control" aria-label="Week ${s.number} completion"><div><strong>${done?'✓ Study completed':'Finished this study?'}</strong><p>After reading, observation, interpretation, application and prayer, mark your study here.</p></div><button class="${done?'secondary':'primary'}-button" data-complete="${s.number}" aria-pressed="${done}">${done?'Mark week '+s.number+' as not completed':'Mark week '+s.number+' as completed'}</button>${ready?`<a class="text-link" href="#story">Return to The Story So Far ↗</a>`:''}</section>`;}
function sceneConnections(s){const item=journey.sessions[s.number-1],m=curriculum.modules.find(m=>m.id===s.module);return `<section class="scene-connections" aria-labelledby="scene-${s.number}"><span class="eyebrow">SCRIPTURE THAT OPENS THE SCENE</span><h4 id="scene-${s.number}">Explore our module question</h4><p class="scene-question">${esc(m.question)}</p><p class="annotation">Read these supporting scenes in their own setting. Notice the connections and the differences, and leave room for the observations and applications the texts raise.</p>${item.connections.map(p=>`<article class="scene-passage"><span class="eyebrow">${esc(p.lens)}</span><h5>${esc(p.title)}</h5><div class="scene-reference">${esc(p.reference)} · WEB</div><blockquote>${p.verses.map(v=>`<p><sup>${v.verse}</sup>${esc(v.text)}</p>`).join('')}</blockquote><p class="scene-prompt">${esc(p.prompt)}</p><a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Read the surrounding chapter ↗</a></article>`).join('')}<button class="text-link" data-tools-tsk="${s.number}">Explore other connections in Bible Study Tools ↗</button></section>`;}
function narrativeReturn(s){const m=curriculum.modules.find(m=>m.id===s.module);return `<section class="narrative-return"><span class="eyebrow">RETURN TO THE BIG STORY</span><h4>${esc(m.question)}</h4><p>${esc(journey.sessions[s.number-1].narrativeQuestion)}</p><p class="annotation">Use the words of the passages to explain your answer. Which questions would you like to carry into the next scene?</p></section>`;}
async function ensureStories(){
 if(approvedStories)return approvedStories;
 if(reflections?.review){approvedStories=reflections;return approvedStories;}
 if(!storyPromise)storyPromise=fetchJSON($('meta[name="story-catalog"]').content,{cache:'no-store'}).then(data=>{approvedStories=data;return data}).catch(e=>{storyPromise=null;throw e});
 return storyPromise;
}
function tskView(){
 const key=state.verse||session().verses[0].key;state.verse=key;const [b,c]=key.split('.'),chap=bible.chapters[b+'.'+c],rows=bible.references[key]||[];
 return `<h3 class="tool-heading">TSK concordance</h3><p class="info-note">Choose a chapter and verse, then read the connected passages. These are exploratory cross references from OpenBible’s TSK-based dataset; always compare the surrounding context.</p><div class="tsk-selectors"><label for="tsk-chapter">Chapter<select id="tsk-chapter">${Object.entries(bible.chapters).map(([id,ch])=>`<option value="${id}" ${id===b+'.'+c?'selected':''}>${esc(ch.book)} ${id.split('.')[1]}</option>`).join('')}</select></label><label for="tsk-verse">Verse<select id="tsk-verse">${Object.keys(chap.verses).map(v=>`<option value="${b}.${c}.${v}" ${key===b+'.'+c+'.'+v?'selected':''}>${v}</option>`).join('')}</select></label></div><section class="side-card"><span class="eyebrow">${esc(verseLabel(key))} · WEB</span><p class="tsk-source-verse">${esc(chap.verses[key.split('.')[2]])}</p><p>${rows.length} connections. Select a passage to read it here.</p><div class="tsk-reference-grid">${rows.slice(0,12).map(r=>`<button class="reference-row" data-ref="${r.ref}"><span>${esc(refLabel(r.ref))}</span><small>↗</small></button>`).join('')}</div>${rows.length>12?`<button class="text-link" data-all-refs="${key}">View all ${rows.length} connections ↗</button>`:''}</section>`;
}
function toolsView(){const names={words:'Repeated words',glossary:'Glossary',tsk:'TSK concordance'};return heading('05','Bible Study Tools','Follow a word, understand an idea, or compare related passages.')+`<div class="tool-tabs" role="tablist" aria-label="Bible study tools">${Object.entries(names).map(([key,name])=>`<button role="tab" id="tool-tab-${key}" aria-controls="tool-panel" aria-selected="${state.tool===key}" tabindex="${state.tool===key?0:-1}" data-tool="${key}">${name}</button>`).join('')}</div><section id="tool-panel" role="tabpanel" aria-labelledby="tool-tab-${state.tool}">${({words,glossary:glossaryView,tsk:tskView}[state.tool])()}</section>`;}
function wireJourney(){
 document.querySelectorAll('[data-review-toggle]').forEach(b=>b.onclick=()=>{reviewParticipant=!reviewParticipant;render();});
 document.querySelectorAll('[data-study-jump]').forEach(b=>b.onclick=()=>$('#study-start-'+b.dataset.studyJump)?.focus());
 document.querySelectorAll('[data-tools-tsk]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.toolsTsk);state.tool='tsk';go('tools');});
 document.querySelectorAll('[data-tool]').forEach(b=>{b.onclick=()=>{state.tool=b.dataset.tool;render();$('#tool-tab-'+state.tool).focus();};b.onkeydown=e=>{const keys=['words','glossary','tsk'],i=keys.indexOf(state.tool);let next;if(e.key==='ArrowRight')next=keys[(i+1)%3];if(e.key==='ArrowLeft')next=keys[(i+2)%3];if(e.key==='Home')next=keys[0];if(e.key==='End')next=keys[2];if(next){e.preventDefault();state.tool=next;render();$('#tool-tab-'+next).focus();}};});
 $('#tsk-chapter')?.addEventListener('change',e=>{state.verse=e.target.value+'.1';render();$('#tsk-chapter').focus();});
 $('#tsk-verse')?.addEventListener('change',e=>{state.verse=e.target.value;render();$('#tsk-verse').focus();});
 document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=async()=>{
  const n=Number(b.dataset.complete),wasDone=completed.includes(n);completed=toggleCompleted(completed,n);
  try{localStorage.setItem('luke-acts-'+progressKey(),JSON.stringify({version:1,completed}));progressSaved=true;}catch{progressSaved=false;}
  if(curriculum.modules.some(m=>storyAvailable(m.id))){try{await ensureStories()}catch{/* Completion stays saved. Opening the reading offers a retry. */}}
  render();document.querySelector(`[data-complete="${n}"]`)?.focus({preventScroll:true});
  showToast(!progressSaved?'Completed for this visit; browser storage is unavailable.':wasDone?'Completion removed.':moduleCompleted(curriculum.sessions[n-1].module,curriculum.sessions,completed)?'Module completed. The Story So Far is open.':'Study completed. Your scene is now open.');
 });
}
window.addEventListener('storage',async e=>{if(curriculum&&e.key==='luke-acts-'+progressKey()){completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))try{await ensureStories()}catch{}if(!$('#detail').open)render();}});
